import sys

def transform(A, B):
    if len(A) != len(B):
        return -1
    count = [0] * 256
    for i in range(len(A)):
        count[ord(A[i])] += 1
        count[ord(B[i])] -= 1
    if any(c != 0 for c in count):
        return -1
    res = 0
    for i in range(len(A) - 1, -1, -1):
        if A[i] == B[i]:
            continue
        j = i
        while j >= 0 and A[j] != B[i]:
            j -= 1
        if j == -1:
            return -1
        while j < i:
            A = A[j+1] + A[:j] + A[j+1:]
            res += 1
            j += 1
    return res

input = sys.stdin.read().strip().split()
A = input[0]
B = input[1]
print(transform(A, B))
